#include <iostream>
#include <optional>
#include <vector>

class Grid
{
public:
    Grid(int w, int h) : m_w{w}, m_h{h}, m_cells(static_cast<std::size_t>(w * h), '.') {}
    std::optional<char> at(int x, int y) const { return std::nullopt; }

private:
    int m_w, m_h;
    std::vector<char> m_cells;
};

int main()
{
    Grid g{6, 4};
}
